        if (!$tokens[$index]->isGivenKind(T_DOC_COMMENT)) {
            continue;
        }

        $targetIndex = $tokens->getTokenNotOfKindSibling(
            $index,
            1,
            [[T_ABSTRACT], [T_COMMENT], [T_FINAL], [T_FUNCTION], [T_PRIVATE], [T_PROTECTED], [T_PUBLIC], [T_STATIC], [T_WHITESPACE]],
